"""Aptitude practice: numerical and logical questions generated by code, verbal from the bank.

Code-generated questions are always correct and never run out. The same day always
gives the same set, so you can close the app and carry on later.
"""

import random

from quiz import pick_daily_questions

APTITUDE_TOPICS = ["numerical", "logical", "verbal"]
CHALLENGE_ID = "aptitude"
TARGET_SECONDS = 60


def _options(rng, correct, distractors):
    """Shuffle the correct answer with three different wrong ones. Returns (options, index)."""
    wrong = []
    for value in distractors:
        if value != correct and value not in wrong:
            wrong.append(value)
    if len(wrong) < 3:
        raise ValueError("Not enough different wrong answers")
    options = [correct] + wrong[:3]
    rng.shuffle(options)
    return options, options.index(correct)


def _fmt(number):
    """Show whole numbers without .0 and others with up to 2 decimals."""
    return str(int(number)) if float(number).is_integer() else f"{number:.2f}".rstrip("0")


# ---------- Numerical ----------

def percentage_change(rng):
    before = rng.choice([200, 240, 300, 320, 400, 480, 500, 600, 800])
    percent = rng.choice([5, 10, 15, 20, 25, 30, 40])
    after = before * (100 + percent) // 100
    wrong_base = round(100 * (after - before) / after, 1)
    question = (
        f"A support team resolved {before} tickets last month and {after} this month. "
        "What is the percentage increase?"
    )
    options, answer = _options(
        rng, f"{percent}%", [f"{_fmt(wrong_base)}%", f"{percent + 5}%", f"{percent * 2}%", f"{percent - 5}%"]
    )
    explanation = (
        f"Increase = {after} - {before} = {after - before}. Percentage increase = increase / "
        f"original × 100 = {after - before} / {before} × 100 = {percent}%. A common mistake is "
        f"dividing by the new value ({after}), which gives {_fmt(wrong_base)}%."
    )
    return question, options, answer, explanation


def sla_adherence(rng):
    total = rng.choice([200, 400, 500, 800, 1000])
    breached = rng.choice([4, 6, 8, 10, 12, 16, 20])
    met = total - breached
    percent = 100 * met / total
    question = (
        f"Out of {total} tickets this quarter, {breached} breached their SLA. "
        "What was the SLA adherence?"
    )
    options, answer = _options(
        rng,
        f"{_fmt(percent)}%",
        [f"{_fmt(100 * breached / total)}%", f"{_fmt(percent - 1)}%", f"{_fmt(min(percent + 1, 99.9))}%", "100%"],
    )
    explanation = (
        f"Tickets within SLA = {total} - {breached} = {met}. Adherence = {met} / {total} × 100 "
        f"= {_fmt(percent)}%."
    )
    return question, options, answer, explanation


def work_rate(rng):
    hours = rng.choice([2.5, 3, 3.5, 4, 4.5, 5, 6])
    per_hour = rng.choice([4, 6, 8, 10, 12] if hours % 1 else [3, 4, 5, 6, 7, 8, 9])
    tickets = int(per_hour * hours)

    def as_time(h):
        whole, minutes = int(h), round((h - int(h)) * 60)
        return f"{whole} h {minutes} min" if minutes else f"{whole} h"

    question = (
        f"An engineer closes {per_hour} tickets per hour. How long will {tickets} tickets take?"
    )
    options, answer = _options(
        rng, as_time(hours), [as_time(hours + 0.5), as_time(hours - 0.5), as_time(hours + 1), as_time(hours * 2)]
    )
    explanation = f"Time = tickets / rate = {tickets} / {per_hour} = {_fmt(hours)} hours = {as_time(hours)}."
    return question, options, answer, explanation


def ratio_split(rng):
    a, b = rng.choice([(1, 2), (2, 3), (1, 4), (2, 5), (3, 4), (2, 7), (3, 5)])
    unit = rng.choice([3, 4, 5, 6, 8, 10])
    total = (a + b) * unit
    question = (
        f"P1 and P2 incidents were in the ratio {a}:{b}. There were {total} in total. "
        "How many were P1?"
    )
    options, answer = _options(rng, str(a * unit), [str(b * unit), str(a * unit + unit), str(total // 2), str(a * unit - unit)])
    explanation = (
        f"Total parts = {a} + {b} = {a + b}. One part = {total} / {a + b} = {unit}. "
        f"P1 = {a} × {unit} = {a * unit}."
    )
    return question, options, answer, explanation


def average(rng):
    while True:
        values = [rng.randint(8, 40) for _ in range(4)]
        mean = rng.randint(15, 30)
        last = mean * 5 - sum(values)
        if 5 <= last <= 60:
            values.append(last)
            break
    question = (
        "Five incidents took these minutes to resolve: "
        + ", ".join(str(v) for v in values)
        + ". What was the average (mean) time?"
    )
    options, answer = _options(rng, f"{mean} min", [f"{mean + 2} min", f"{mean - 3} min", f"{sorted(values)[2]} min", f"{mean + 5} min"])
    explanation = f"Mean = sum / count = {sum(values)} / 5 = {mean} minutes."
    return question, options, answer, explanation


# ---------- Logical ----------

def arithmetic_sequence(rng):
    start, step = rng.randint(2, 30), rng.choice([3, 4, 6, 7, 9, 11, 13])
    terms = [start + step * i for i in range(5)]
    nxt = start + step * 5
    question = "What number comes next? " + ", ".join(map(str, terms)) + ", ?"
    options, answer = _options(rng, str(nxt), [str(nxt + 1), str(nxt - step + 1), str(nxt + step), str(nxt - 1)])
    explanation = f"Each number goes up by {step}. {terms[-1]} + {step} = {nxt}."
    return question, options, answer, explanation


def geometric_sequence(rng):
    start, ratio = rng.choice([1, 2, 3, 5]), rng.choice([2, 3])
    terms = [start * ratio ** i for i in range(5)]
    nxt = start * ratio ** 5
    question = "What number comes next? " + ", ".join(map(str, terms)) + ", ?"
    options, answer = _options(rng, str(nxt), [str(terms[-1] + (terms[-1] - terms[-2])), str(nxt + ratio), str(nxt - start), str(terms[-1] * (ratio + 1))])
    explanation = f"Each number is multiplied by {ratio}. {terms[-1]} × {ratio} = {nxt}."
    return question, options, answer, explanation


def alternating_sequence(rng):
    start = rng.randint(1, 20)
    a, b = rng.sample([2, 3, 4, 5, 6, 7, 8], 2)
    terms = [start]
    for i in range(5):
        terms.append(terms[-1] + (a if i % 2 == 0 else b))
    nxt = terms[-1] + b
    question = "What number comes next? " + ", ".join(map(str, terms)) + ", ?"
    options, answer = _options(rng, str(nxt), [str(terms[-1] + a), str(nxt + 1), str(nxt - 2), str(terms[-1] + a + b)])
    explanation = f"The steps alternate: +{a}, +{b}, +{a}, +{b}, +{a}… The next step is +{b}, so {terms[-1]} + {b} = {nxt}."
    return question, options, answer, explanation


def squares_sequence(rng):
    offset = rng.choice([0, 1, -1, 2, 3])
    first = rng.randint(1, 4)
    terms = [(first + i) ** 2 + offset for i in range(5)]
    nxt = (first + 5) ** 2 + offset
    question = "What number comes next? " + ", ".join(map(str, terms)) + ", ?"
    diff = terms[-1] - terms[-2]
    options, answer = _options(rng, str(nxt), [str(terms[-1] + diff), str(nxt + 2), str(nxt - 1), str(terms[-1] * 2)])
    rule = "square numbers" if offset == 0 else f"square numbers {'+' if offset > 0 else '-'} {abs(offset)}"
    explanation = (
        f"These are {rule}: the gaps grow by 2 each time ({diff - 2}, {diff}, then {diff + 2}). "
        f"{terms[-1]} + {diff + 2} = {nxt}."
    )
    return question, options, answer, explanation


def fibonacci_sequence(rng):
    a, b = rng.randint(1, 6), rng.randint(2, 9)
    terms = [a, b]
    for _ in range(4):
        terms.append(terms[-1] + terms[-2])
    nxt = terms[-1] + terms[-2]
    question = "What number comes next? " + ", ".join(map(str, terms)) + ", ?"
    options, answer = _options(rng, str(nxt), [str(terms[-1] * 2), str(nxt + 1), str(terms[-1] + (terms[-1] - terms[-2])), str(nxt - 2)])
    explanation = f"Each number is the sum of the two before it: {terms[-2]} + {terms[-1]} = {nxt}."
    return question, options, answer, explanation


GENERATORS = {
    "numerical": [percentage_change, sla_adherence, work_rate, ratio_split, average],
    "logical": [arithmetic_sequence, geometric_sequence, alternating_sequence, squares_sequence, fibonacci_sequence],
}


def generate(topic, rng, question_id):
    """Make one code-generated question in the same format as the question bank."""
    make = rng.choice(GENERATORS[topic])
    question, options, answer, explanation = make(rng)
    return {
        "id": question_id,
        "topic": topic,
        "question": question,
        "options": options,
        "answer": answer,
        "explanation": explanation,
    }


def daily_aptitude(bank, day, history=None, per_topic=2):
    """Today's aptitude set: numerical and logical (generated) plus verbal (from the bank)."""
    rng = random.Random(f"aptitude-{day.isoformat()}")
    questions = []
    for topic in ["numerical", "logical"]:
        for n in range(per_topic):
            questions.append(generate(topic, rng, f"apt-{topic}-{day.isoformat()}-{n}"))
    questions += pick_daily_questions(
        bank, ["verbal"], day, job_id=CHALLENGE_ID, count=per_topic, history=history
    )
    return questions
